#!/usr/bin/env python3
"""Compressed, hash-checked carrier for the readable Part 5 regression harness.
Run directly, or pass --extract PATH to inspect the expanded source.
"""
import base64, gzip, hashlib, sys
from pathlib import Path
EXPECTED_SHA256 = "144fa95486e9ba5185d22b439052cb3a0503bcc2a5788040ad1c606147138e86"
PAYLOAD = ""
source = gzip.decompress(base64.b64decode(PAYLOAD))
observed = hashlib.sha256(source).hexdigest()
if observed != EXPECTED_SHA256:
    raise SystemExit(f"expanded source SHA-256 mismatch: {observed}")
if len(sys.argv) == 3 and sys.argv[1] == "--extract":
    target = Path(sys.argv[2])
    target.write_bytes(source)
    print(f"EXTRACTED={target}")
    print(f"EXPANDED_SOURCE_SHA256={observed}")
elif len(sys.argv) == 1:
    exec(compile(source, "AIEFS_Part5_v41_trust_anchor_regression.py", "exec"),
         {"__name__": "__main__", "__file__": "AIEFS_Part5_v41_trust_anchor_regression.py"})
else:
    raise SystemExit("usage: reproducer.py [--extract PATH]")
